insert into casos (id, materia, bloque, u, nivel, ambito, titulo, escenario, conceptos, desarrollo_consigna, desarrollo_rubrica) values
  (1, 'etica', 1, 1, 'Sencilla', 'Salud pública', 'Camas de terapia intensiva asignadas por score', 'Durante una ola de bronquiolitis, un hospital provincial tiene 6 camas de terapia intensiva y 14 pacientes que las necesitan. Un sistema de IA estima la probabilidad de supervivencia de cada paciente con cama. La dirección decide asignarlas a quienes el sistema calcula que tienen más chances, lo que deja afuera sobre todo a pacientes con enfermedades crónicas. Una médica de guardia se niega a aplicar el criterio sin revisar cada caso, y un grupo de familias pide que las reglas de asignación se discutan públicamente antes de la próxima ola.', 'Teorías éticas, crítica al utilitarismo, contractualismo, virtud, supervisión humana', 'Como integrante del comité de bioética, redactá una recomendación sobre el uso del sistema en la próxima ola: identificá el problema ético, los principios en conflicto y fundamentá qué regla de asignación adoptarías.', '["Nombra el conflicto: maximizar vidas (eficiencia) vs igual consideración / no discriminación de crónicos", "Usa al menos dos teorías (utilitarismo y su crítica; contractualismo o deontología)", "Distingue supervisión humana formal de material y exige revisión clínica real", "Propone medidas: validar el modelo por subgrupos (crónicos), criterios públicos, instancia de revisión", "Toma posición explícita y dice quién responde por la decisión", "Menciona proporcionalidad o que el score no debe ser el único fundamento"]'::jsonb),
  (2, 'etica', 1, 1, 'Compleja', 'Estudio contable', 'El informe alucinado sobre un cliente', 'Un estudio contable de Rosario usa un asistente de IA generativa para resumir la situación fiscal de clientes antes de reuniones con bancos. Para obtener mejores respuestas, los empleados pegan en el chat balances completos, CUIT, nombres de socios y detalles de salud de uno de ellos que explican una baja de ingresos. En un informe, el asistente inventa que un cliente tuvo un embargo por evasión. El contador lo envía al banco sin verificar y el crédito se rechaza. El proveedor del asistente sostiene que sus términos advierten que las respuestas pueden contener errores.', 'Alucinaciones, sesgo de autoridad tecnológica, caso Walters, privacidad en el prompting, minimización, datos de terceros', 'El cliente perjudicado reclama. Analizá quién debería responder y qué debería cambiar el estudio en su uso de IA generativa.', '["Identifica la alucinación y el sesgo de autoridad tecnológica", "Distribuye responsabilidad: deber de verificación del profesional y crítica a los disclaimers del proveedor", "Detecta el problema de privacidad: datos de terceros, dato sensible de salud, secreto profesional", "Aplica minimización / necesidad contextual con medidas concretas", "Cita Walters c/ OpenAI (y opcionalmente In re OpenAI)", "Toma posición y propone gobernanza (herramientas autorizadas, verificación obligatoria, registro de usos)"]'::jsonb),
  (3, 'etica', 2, 2, 'Compleja', 'Fintech', 'El scoring «ciego» de una billetera virtual', 'Una billetera virtual lanza microcréditos con un modelo entrenado con 6 años de historial de pagos. Para «evitar discriminación» quitó sexo, edad y nacionalidad. Usa código postal, tipo de celular, horario de uso de la app y recargas en efectivo. La accuracy global es 90 %. Una ONG obtiene datos desagregados: entre quienes realmente pagaron, el modelo aprobó al 88 % de los usuarios de barrios céntricos y al 61 % de barrios populares; entre quienes no pagaron, aprobó al 9 % y al 7 % respectivamente. La empresa responde que el modelo «sólo refleja el comportamiento histórico».', 'Data governance, proxies, sesgo sistémico, accuracy vs fairness, métricas de fairness', 'La billetera te contrata para auditar el modelo. Redactá tu diagnóstico y tu recomendación.', '["Explica proxies y por qué el modelo no es ciego", "Usa los números para mostrar la violación de equal opportunity (y de equalized odds)", "Distingue accuracy de fairness", "Refuta «refleja la realidad» con sesgo sistémico", "Justifica qué métrica elegiría y reconoce que es una decisión normativa (Chouldechova)", "Propone medidas y menciona que crédito es alto riesgo en el AI Act / accountability"]'::jsonb),
  (4, 'etica', 2, 2, 'Compleja', 'Universidad', 'El semáforo de abandono que se volvió profecía', 'Una universidad privada implementó en 2023 un sistema que clasifica a cada estudiante en verde, amarillo o rojo según su riesgo de abandono, usando asistencia presencial, uso del campus virtual y notas. Los tutores dan más horas a los verdes «porque rinden» y a los rojos les ofrecen pasarse a la modalidad a distancia. En 2026 la mayoría cursa híbrido y la asistencia presencial dejó de indicar compromiso; la precisión cayó del 88 % al 71 %. Nadie lo revisó porque el contrato con el proveedor no prevé monitoreo. Cuando un estudiante reclama, el área académica dice que la clasificación la hace el proveedor, el proveedor dice que la universidad decide qué hacer y los tutores dicen que sólo siguen el color.', 'Drift, profecía autocumplida, ALTAI, accountability, responsabilidad diluida', 'Redactá el informe del comité de ética de la universidad: qué falló, quién responde y qué condiciones pondrías para seguir usando el semáforo.', '["Distingue concept drift y model drift con los datos del caso", "Explica la profecía autocumplida y la conecta con bienestar / ALTAI", "Identifica responsabilidad diluida y asigna responsables (universidad deployer, proveedor provider)", "Propone monitoreo → revalidación → reentrenamiento o retiro, no auditorías por calendario", "Plantea supervisión humana material y transparencia hacia el estudiante", "Toma posición sobre continuar, suspender o rediseñar"]'::jsonb),
  (5, 'etica', 3, 2, 'Sencilla', 'Empresa de software', 'Tres productos, una empresa argentina y clientes en España', 'Una empresa cordobesa vende tres productos a clientes de España: (1) un sistema que analiza la voz y el rostro de los operadores de call center para inferir su estrés y su nivel de entusiasmo durante la jornada; (2) un chatbot de atención que se presenta como «Lucía, del equipo de soporte» sin aclarar que es IA; (3) un filtro que lee CV y descarta automáticamente al 85 % antes de que los vea Recursos Humanos. Un banco español compró el tercer producto y lo usa para contratar.', 'AI Act, niveles de riesgo, prácticas prohibidas, transparencia, provider y deployer, alcance extraterritorial', 'La empresa quiere seguir vendiendo en Europa. Armá un plan de compliance para los tres productos, justificando cada decisión con el principio ético que hay detrás.', '["Clasifica correctamente los tres productos (prohibido, transparencia, alto riesgo)", "Explica el principio detrás de cada nivel (dignidad/autonomía, transparencia, no discriminación)", "Distingue provider y deployer y sus obligaciones", "Enumera obligaciones de alto riesgo (datos, logs, documentación, supervisión efectiva, robustez)", "Menciona que la supervisión en el filtro de CV es formal y cómo volverla material", "Menciona sanciones o que el compliance es dinámico (AI Omnibus)"]'::jsonb),
  (6, 'etica', 3, 2, 'Compleja', 'Startup de IA generativa', 'Las ilustraciones que eran demasiado parecidas', 'PincelAI, una startup, entrena un generador de ilustraciones infantiles con millones de imágenes descargadas de sitios de ilustradores, incluidas obras de autores que habían publicado una reserva de derechos legible por máquina. Con prompts simples como «oso con bufanda estilo cuento nórdico», el modelo devuelve imágenes casi idénticas a portadas de libros conocidos. PincelAI sostiene que el modelo «aprende patrones, no guarda copias», que el parecido lo provoca el usuario con su prompt y que el entrenamiento se hizo en servidores de Estados Unidos.', 'GEMA c/ SUNO, training / memorization / output, Text and Data Mining, AI Act art. 53, distribución del valor', 'Sos parte del tribunal. Resolvé si PincelAI infringió derechos y qué debería cambiar, incluyendo la dimensión ética de fondo.', '["Separa training, memorization y output", "Analiza TDM y el opt-out machine-readable", "Atribuye responsabilidad por el output con fundamentos (control del proveedor, prompts simples)", "Rechaza las simplificaciones «siempre fair use» / «nunca fair use»", "Plantea la pregunta ética: distribución del valor entre creadores y plataforma", "Propone medidas técnicas y menciona el art. 53 del AI Act o la superposición de capas"]'::jsonb),
  (7, 'etica', 4, 3, 'Compleja', 'Municipio', 'Las vacantes de jardín que decidió un software', 'Un municipio del conurbano asigna las vacantes de jardines maternales con un software comprado a una empresa privada, que ordena a las familias por puntaje y rechaza automáticamente a las que quedan fuera del cupo. Mariela, madre soltera con trabajo nocturno, queda afuera y pide saber por qué. El municipio le responde: «no alcanzó el puntaje». La empresa se niega a informar las variables y sus pesos por secreto comercial, y agrega que publicar la lógica permitiría que las familias «manipulen» sus datos. No existe ninguna instancia de revisión.', 'Transparencia, explicabilidad, contrafactual, secreto comercial, BOSCO, Dun & Bradstreet, art. 20 Ley 25.326, contestabilidad', 'Mariela te consulta como especialista. Identificá qué principios fueron vulnerados, qué puede reclamar y cómo debería rediseñarse el sistema.', '["Distingue transparencia, explicabilidad y contestabilidad y cuáles fallaron", "Plantea la ponderación secreto comercial / seguridad vs derecho a explicación con BOSCO y Dun & Bradstreet", "Aplica el art. 20 Ley 25.326 (y hábeas data para acceso a sus datos)", "Detecta la ausencia de revisión humana y de trazabilidad", "Propone explicación contrafactual, revisión humana material y auditoría con acceso reservado", "Considera posibles proxies o impacto en familias vulnerables (fairness)"]'::jsonb),
  (8, 'etica', 4, 3, 'Compleja', 'Hospital', 'La alerta de sepsis que fallaba con los mayores', 'Un hospital usa un modelo que alerta sobre riesgo de sepsis. Fue entrenado con datos de un hospital de Estados Unidos con población mayormente joven. La accuracy global es 93 %. Una residente desagrega: entre pacientes que efectivamente desarrollaron sepsis, el sistema alertó al 90 % de los menores de 60 y al 64 % de los mayores de 75. Además, los enfermeros atienden 40 alertas por turno y descartan el 80 % sin revisar. La dirección dice que no puede cambiar el umbral porque «bajar el threshold llenaría la guardia de falsas alarmas».', 'Accuracy vs fairness, falsos negativos, equal opportunity, threshold, validación por subgrupo (Ewert), automation bias y fatiga', 'Como parte del comité de calidad, recomendá qué hacer con el sistema de alertas. Fundamentá con conceptos y principios.', '["Muestra la violación de equal opportunity con los datos (90 vs 64)", "Explica por qué el falso negativo es el error crítico y cómo eso orienta el threshold", "Identifica sesgo por representación / validación en otra población (Ewert)", "Distingue supervisión formal (fatiga, 80 % descartado) de material", "Propone medidas concretas (revalidar con datos locales, umbral por evaluación de impacto, gestión de alertas, monitoreo)", "Toma posición y señala responsables"]'::jsonb),
  (9, 'etica', 5, 3, 'Sencilla', 'Plataforma de reparto', 'El repartidor desconectado por su rating', 'RapiYa, una app de delivery en Buenos Aires, dice que sus repartidores son «socios independientes» que eligen cuándo conectarse. El algoritmo asigna los mejores pedidos y franjas horarias a quienes tienen mejor puntaje, baja el puntaje a quien rechaza pedidos, fija la tarifa de cada viaje y desconecta automáticamente por 48 horas a quien cae por debajo de 4,2 estrellas. Nicolás, repartidor hace tres años, fue desconectado tras varias malas calificaciones en días de lluvia y no tiene a quién reclamar.', 'Gestión algorítmica, autonomía formal vs real, Uber v. Aslam, Glovo, contestabilidad, accountability', 'Escribí la posición de un tribunal laboral sobre el caso de Nicolás: cómo califica la relación y qué exige a RapiYa sobre su algoritmo.', '["Identifica gestión algorítmica y los mecanismos de control (asignación, tarifa, puntaje, desconexión)", "Aplica Uber v. Aslam y Glovo (realidad sobre etiqueta, ajenidad, dependencia)", "Explica la paradoja de la flexibilidad", "Señala el bias del rating (factores externos como la lluvia)", "Exige transparencia, explicación y revisión humana antes de sancionar", "Plantea la pregunta distributiva o de calidad del empleo"]'::jsonb),
  (10, 'etica', 5, 3, 'Compleja', 'Gobierno provincial', 'Un tutor de IA para todas las escuelas rurales', 'Una provincia anuncia «IA para todos»: cada estudiante secundario tendrá acceso a un tutor basado en un modelo generativo de gran tamaño, que resolverá tareas y corregirá ejercicios. El 40 % de las escuelas rurales tiene conexión inestable y muchos alumnos sólo cuentan con un celular compartido. Para abaratar costos, el gobierno acuerda instalar un data center en una zona con sequías recurrentes. Un grupo de docentes advierte que los alumnos ya entregan respuestas del tutor sin entenderlas.', 'Brecha digital y AI divide, deskilling, determinismo tecnológico, impacto ambiental, Green AI, efecto rebote', 'Te piden un dictamen para la legislatura provincial sobre el programa «IA para todos». Evaluá su impacto social y ambiental y proponé condiciones.', '["Usa la pregunta distributiva (quién gana, pierde, decide, paga)", "Analiza brecha digital / AI divide con datos del caso", "Explica deskilling y propone diseño pedagógico para evitarlo", "Analiza impacto ambiental (agua, ubicación, inferencia masiva, efecto rebote)", "Aplica Green AI (modelo adecuado, medición)", "Evita determinismo y toma posición condicionada"]'::jsonb),
  (11, 'etica', 6, 4, 'Compleja', 'Supermercado', 'La tarjeta de puntos que sabía demasiado', 'Una cadena de supermercados ofrece una tarjeta de puntos. Al adherirse, el cliente acepta «términos y condiciones» de 40 páginas para «recibir beneficios». Con el historial de compras, un modelo infiere embarazos, enfermedades crónicas (por compras de productos sin gluten o para diabéticos) y dificultades económicas, y ajusta los precios personalizados de la app: a quienes infiere en dificultades les muestra menos descuentos porque «tienen menor sensibilidad a promociones». La empresa también quiere vender a una aseguradora un «índice de salud» por cliente. Los datos se guardan sin plazo «por si sirven para futuros modelos». La cadena opera en Argentina y tiene tienda online con envíos a España.', 'Finalidad, minimización, conservación, datos inferidos, datos sensibles, consentimiento, bases jurídicas, alcance del GDPR, fairness', 'La autoridad de datos (AAIP) recibe una denuncia. Redactá el análisis: normas aplicables, principios vulnerados y medidas.', '["Identifica datos inferidos y datos sensibles de salud", "Analiza el consentimiento (requisitos) y que no es la única base", "Aplica finalidad, minimización y conservación (GDPR art. 5 y Ley 25.326 art. 4)", "Detecta el alcance extraterritorial del GDPR por los envíos a España", "Separa protección de datos de fairness en los precios personalizados", "Propone medidas (DPIA, privacy by default, plazos, prohibir venta del índice) y toma posición"]'::jsonb),
  (12, 'etica', 6, 4, 'Sencilla', 'Buscadores', 'Dos pedidos de desindexación en el mismo buzón', 'Un buscador recibe dos pedidos la misma semana. (1) Ramiro, un kinesiólogo sin actividad pública, pide que al buscar su nombre dejen de aparecer notas de 2011 sobre un concurso de acreedores de su consultorio, que terminó cerrado y pagado en 2013; dice que pierde pacientes. (2) Un exintendente que hoy es candidato a diputado pide desindexar notas de 2014 sobre una investigación por irregularidades en contrataciones durante su gestión, que siguen citándose en debates públicos. Ambos invocan el «derecho al olvido».', 'Derecho al olvido, desindexación vs supresión, ponderación, Costeja, Denegri, interés público, figura pública', 'Sos el responsable legal del buscador. Resolvé ambos pedidos con fundamentos y explicá qué preguntas usaste para ponderar.', '["Distingue desindexación de supresión", "Enumera las preguntas de ponderación (veracidad, actualidad, proyección pública, interés público, antigüedad y daño, qué se pide)", "Resuelve Ramiro con Costeja", "Resuelve al exintendente con Denegri", "Explica que no son fallos contradictorios", "Menciona el rol del buscador (trata datos, es responsable, ranking = visibilidad)"]'::jsonb);
insert into preguntas (id, caso_id, sub, texto, opciones) values
  ('etica-1-a', 1, 'a', '¿Qué teoría ética expresa mejor el criterio adoptado por la dirección?', '{"a": "Contractualismo, porque la regla se apoya en un criterio objetivo que cualquier paciente aceptaría si conociera las probabilidades.", "b": "Utilitarismo, porque elige la asignación que maximiza el resultado agregado: más vidas salvadas con los recursos disponibles.", "c": "Deontología, porque trata a todos los pacientes con la misma regla y no hace excepciones según quién sea cada uno de ellos.", "d": "Ética de la virtud, porque la dirección actúa con prudencia al apoyarse en el mejor dato técnico disponible para decidir."}'::jsonb),
  ('etica-1-b', 1, 'b', '¿Cuál es la objeción más fuerte contra ese criterio, según la clase 1?', '{"a": "Que ignora las consecuencias de las decisiones y se limita a aplicar reglas fijas, sin importar qué le pase a cada paciente.", "b": "Que exige conocer con certeza la probabilidad de supervivencia de cada paciente, algo que ningún modelo estadístico puede ofrecer.", "c": "Que reemplaza el juicio clínico por el de la dirección y, con eso, vulnera la autonomía profesional de la médica de guardia.", "d": "Que el cálculo agregado puede avalar perjudicar de forma sistemática a una minoría (los crónicos) si eso mejora el saldo global."}'::jsonb),
  ('etica-1-c', 1, 'c', 'Las familias piden discutir públicamente las reglas antes de la próxima ola. ¿Qué enfoque respalda ese pedido?', '{"a": "El contractualismo: una regla es legítima si puede justificarse ante todos los afectados, incluido quien queda peor ubicado.", "b": "El utilitarismo: discutir en público mejora la aceptación social de la regla y, con eso, el bienestar agregado del hospital.", "c": "La deontología: cada paciente debe ser tratado como fin en sí mismo, y eso se garantiza consultando previamente a las familias.", "d": "La ética de la virtud: un hospital virtuoso escucha a las familias, porque la deliberación conjunta forma el carácter institucional."}'::jsonb),
  ('etica-1-d', 1, 'd', '¿Cómo se describe mejor la actitud de la médica que revisa cada caso?', '{"a": "Automation bias: deposita su confianza en el sistema, aunque luego lo corrige caso por caso según su experiencia clínica.", "b": "Deontología estricta: se niega a aceptar una regla que perjudique a algunos pacientes, sin considerar sus consecuencias globales.", "c": "Prudencia (justo medio): usa el modelo pero audita sus límites, evitando tanto rechazarlo por completo como aceptarlo a ciegas.", "d": "Vicio por defecto: rechaza el modelo por desconfianza general y decide por su cuenta, sin apoyarse en ningún dato del sistema."}'::jsonb),
  ('etica-2-a', 2, 'a', '¿Qué fenómeno describe mejor por qué el contador envió el informe sin verificarlo?', '{"a": "Sesgo de confirmación: el contador buscó en el informe lo que ya creía sobre la situación fiscal del cliente ante el banco.", "b": "Sesgo de omisión: el asistente calló información relevante del cliente y el contador completó ese hueco por su propia cuenta.", "c": "Sesgo de autoridad tecnológica: una respuesta fluida y segura parece objetiva y se acepta sin contrastarla con otra fuente.", "d": "Concept drift: la situación fiscal del cliente cambió luego del entrenamiento y el modelo quedó desactualizado respecto de él."}'::jsonb),
  ('etica-2-b', 2, 'b', 'El proveedor invoca sus advertencias. ¿Qué crítica de la cátedra al caso Walters aplica mejor?', '{"a": "Que los disclaimers no bastan: el lenguaje del asistente induce confianza, y omitir controles puede generar responsabilidad sin dolo.", "b": "Que la responsabilidad recae en el proveedor, porque el usuario profesional confió razonablemente en una herramienta comercial.", "c": "Que los disclaimers son válidos si están redactados con claridad, porque el usuario acepta el riesgo al aceptar los términos.", "d": "Que no hay responsabilidad sin dolo, y como el error fue una alucinación y no una intención, no corresponde atribuirlo a nadie."}'::jsonb),
  ('etica-2-c', 2, 'c', 'Sobre la información que los empleados pegaron en el chat, ¿cuál es el análisis correcto?', '{"a": "Los términos del proveedor cubren el tratamiento, ya que quien los acepta responde por los datos que carga en la herramienta.", "b": "Si el prompt sólo se usa para resumir y la salida no se conserva, no hay tratamiento de datos personales relevante.", "c": "Borrar la conversación después de obtener el resumen elimina el riesgo, porque la supresión de la cuenta destruye los datos.", "d": "El consentimiento de quien aceptó los términos no reemplaza la base jurídica para datos de terceros, y la salud es dato sensible."}'::jsonb),
  ('etica-2-d', 2, 'd', '¿Qué medida refleja mejor el principio de necesidad contextual?', '{"a": "Reemplazar los nombres por iniciales y conservar CUIT y balances completos, para que el resumen resulte lo más preciso posible.", "b": "Estructurar los prompts con categorías y roles en lugar de nombres, y reinsertar las identidades recién en el análisis local.", "c": "Enviar el contexto completo por un canal cifrado de extremo a extremo, ya que lo que hay que proteger es la transmisión.", "d": "Sumar más contexto a cada prompt para reducir las alucinaciones, y pedir al proveedor el compromiso de no reutilizar los datos."}'::jsonb),
  ('etica-3-a', 3, 'a', '¿Por qué quitar sexo, edad y nacionalidad no vuelve «ciego» al modelo?', '{"a": "Porque los atributos sensibles siguen presentes en los registros de entrenamiento y el modelo los usa aunque no figuren como columnas.", "b": "Porque un modelo sin atributos protegidos no puede medirse por grupo, y sin esa medición no se puede afirmar que sea justo.", "c": "Porque quitarlos reduce la accuracy y el modelo compensa sobreajustando al historial de pago de los grupos más numerosos.", "d": "Porque variables como código postal o recargas en efectivo pueden actuar como proxies de nivel socioeconómico y reconstruir el sesgo."}'::jsonb),
  ('etica-3-b', 3, 'b', 'Con los datos de la ONG, ¿qué métrica de fairness se incumple claramente?', '{"a": "Predictive parity: la proporción de aprobados que terminan pagando difiere entre barrios, como se ve en los porcentajes informados.", "b": "Equal opportunity: entre quienes efectivamente pagaron, el modelo aprueba al 88 % de un grupo y sólo al 61 % del otro.", "c": "Demographic parity: la tasa total de aprobación difiere entre barrios, y eso surge de forma directa de las cifras de la ONG.", "d": "Ninguna se incumple: entre quienes no pagaron la aprobación es casi igual (9 % y 7 %), lo que muestra un trato equivalente."}'::jsonb),
  ('etica-3-c', 3, 'c', 'La empresa dice que el modelo «sólo refleja el comportamiento histórico». ¿Cuál es la mejor respuesta?', '{"a": "Es válido si los datos son reales y fueron bien cargados: un sistema entrenado con hechos verdaderos no puede resultar injusto.", "b": "Es válido si la empresa publica el código y las variables usadas, porque la transparencia alcanza para descartar discriminación.", "c": "Reflejar desigualdades históricas con precisión es sesgo sistémico: reproducirlas no es neutralidad, es perpetuarlas.", "d": "Es parcialmente válido: la empresa responde por el sesgo que ella introduzca, no por el que ya existía en los datos de origen."}'::jsonb),
  ('etica-3-d', 3, 'd', '¿Qué medida de data governance y fairness corresponde recomendar primero?', '{"a": "Evaluar los resultados desagregados por grupo, revisar los proxies y definir con los afectados qué métrica de fairness se adopta.", "b": "Volver a incluir sexo, edad y nacionalidad para ganar precisión global, ya que el modelo actual pierde información relevante.", "c": "Subir el umbral de aprobación para toda la cartera y así reducir la mora total sin modificar las variables del modelo.", "d": "Reemplazarlo por un modelo más complejo que capture mejor los patrones y reduzca el error en los barrios populares."}'::jsonb),
  ('etica-4-a', 4, 'a', '¿Qué tipo de drift describe mejor que la asistencia presencial ya no indique compromiso?', '{"a": "Concept drift: cambió la relación entre la asistencia presencial y lo que se quiere predecir, aunque los datos sigan llegando igual.", "b": "Data drift: cambió la distribución de los inputs, por lo que el modelo recibe valores fuera del rango con el que fue entrenado.", "c": "Model drift por cambio de código: el proveedor actualizó el sistema en 2026 y el nuevo algoritmo pondera distinto la asistencia.", "d": "Sesgo de medición: la asistencia siempre fue una mala variable, y la caída de precisión recién la hizo visible en 2026."}'::jsonb),
  ('etica-4-b', 4, 'b', '¿Qué riesgo ético concreto genera, para los estudiantes marcados en rojo, la forma en que los tutores usan la clasificación?', '{"a": "Discriminación directa: la regla del sistema usa una categoría protegida para decidir quién recibe menos horas de tutoría.", "b": "Sesgo de confirmación: los tutores buscan pruebas de que los verdes rinden más y descuidan los datos que contradicen al modelo.", "c": "Profecía autocumplida: si los rojos reciben menos apoyo, puede producirse el abandono que el sistema decía anticipar.", "d": "Un problema técnico de calibración: el umbral entre amarillo y rojo está mal ajustado y se corrige reentrenando el modelo."}'::jsonb),
  ('etica-4-c', 4, 'c', '¿Qué pregunta de ALTAI debió hacerse antes del despliegue para evitar ese efecto?', '{"a": "¿El proveedor documentó la arquitectura del modelo y las métricas de precisión obtenidas durante la validación inicial?", "b": "¿La clasificación ayuda al estudiante a identificar necesidades, o puede estigmatizarlo y reducir sus oportunidades?", "c": "¿Los datos de asistencia y de uso del campus virtual se almacenan cifrados y con acceso restringido al personal autorizado?", "d": "¿El sistema se probó en un piloto antes del despliegue y su precisión inicial superó el umbral fijado por la universidad?"}'::jsonb),
  ('etica-4-d', 4, 'd', 'Área académica, proveedor y tutores se señalan entre sí. ¿Cómo se califica y cómo se resuelve?', '{"a": "Es responsabilidad compartida: cada actor cubre su tramo, y alcanza con que el contrato distribuya los riesgos entre las partes.", "b": "Es responsabilidad del proveedor: construyó y entrenó el sistema, así que responde por el uso que hace de él la universidad.", "c": "Es responsabilidad de los tutores: son quienes aplican la clasificación al alumno, por lo que responden por sus efectos.", "d": "Es responsabilidad diluida: corresponde fijar de antemano obligaciones concretas, con decisiones reconstruibles y alguien que responda."}'::jsonb),
  ('etica-5-a', 5, 'a', '¿Cómo clasificaría el AI Act el producto (1), inferencia de emociones de los operadores?', '{"a": "Alto riesgo: al afectar el empleo exige documentación, supervisión humana efectiva y evaluación de conformidad antes de usarse.", "b": "Práctica prohibida como regla: inferir emociones de los trabajadores en su lugar de trabajo está vedado, salvo excepciones acotadas.", "c": "Riesgo de transparencia: alcanza con avisar a los operadores que se analizan sus emociones y obtener su conformidad.", "d": "Riesgo mínimo: analiza voz y rostro con fines de bienestar y no toma decisiones formales sobre los operadores."}'::jsonb),
  ('etica-5-b', 5, 'b', 'El chatbot «Lucía» (producto 2) no aclara que es IA. ¿Cuál es el encuadre correcto?', '{"a": "Riesgo de transparencia: el problema no es el chatbot en sí, sino que la persona no sepa que está interactuando con una máquina.", "b": "Práctica prohibida por manipulación: el nombre humano busca generar confianza indebida y altera la decisión del cliente.", "c": "Alto riesgo: la atención al cliente de una empresa con clientes en la UE requiere evaluación de conformidad y registro.", "d": "Riesgo mínimo: los chatbots comerciales quedan fuera de las obligaciones del reglamento mientras no traten datos sensibles."}'::jsonb),
  ('etica-5-c', 5, 'c', 'Respecto del filtro de CV (producto 3), ¿qué rol tiene cada empresa?', '{"a": "Ambos son providers, porque el banco lo incorporó a su proceso de selección y lo puso a funcionar con sus propios criterios.", "b": "El banco es provider porque decide para qué se usa el sistema, y la empresa cordobesa es deployer del software que le vendió.", "c": "La empresa cordobesa es provider, pero sólo ella responde: el banco es un usuario final sin obligaciones propias en el reglamento.", "d": "La empresa cordobesa es provider (lo desarrolla y comercializa); el banco es deployer (lo usa bajo su autoridad). Ambos tienen obligaciones."}'::jsonb),
  ('etica-5-d', 5, 'd', 'El banco dice que «hay supervisión humana porque RR.HH. elige entre los finalistas». ¿Qué respondés?', '{"a": "Alcanza: el reglamento pide que un humano conserve la decisión final de contratación, y RR.HH. la tiene sobre los finalistas.", "b": "Alcanza si RR.HH. ve el score asignado a cada finalista y puede modificar el orden antes de elegir a quién contratar.", "c": "No alcanza: si el filtro ya descartó al 85 %, la decisión material se tomó antes de que intervenga una persona en el proceso.", "d": "No alcanza, pero se resuelve con una revisión de una muestra de los CV descartados, hecha una vez por año."}'::jsonb),
  ('etica-6-a', 6, 'a', 'Según la lógica del fallo GEMA c/ SUNO, ¿qué dato técnico es jurídicamente determinante?', '{"a": "La escala del dataset: cuantas más obras se usan en el entrenamiento, más probable es que el tribunal vea una infracción.", "b": "La arquitectura: los modelos difusivos no almacenan obras por cómo están diseñados, así que quedan fuera de la reproducción.", "c": "El grado de memorization: que las obras del dataset puedan reproducirse desde el modelo con prompts simples y sin mayor esfuerzo.", "d": "La jurisdicción de entrenamiento: la ley del país donde están los servidores define si hubo o no reproducción de obras."}'::jsonb),
  ('etica-6-b', 6, 'b', '¿Aplica la excepción de Text and Data Mining a las obras con reserva legible por máquina?', '{"a": "Sí: la excepción cubre cualquier entrenamiento con contenido público, y la reserva del titular sólo vale para uso directo de la obra.", "b": "Sí, siempre que no se comercialicen las imágenes generadas, porque la excepción está pensada para usos de investigación.", "c": "No, porque el TDM está pensado para textos y bases de datos, y no cubre imágenes ni música en ningún caso.", "d": "No: el titular puede reservar sus derechos en formato legible por máquina, y con esa reserva la excepción no alcanza al entrenamiento."}'::jsonb),
  ('etica-6-c', 6, 'c', 'PincelAI dice que el parecido lo causa el usuario con su prompt. ¿Qué respondería el razonamiento de Múnich?', '{"a": "Con prompts simples y con datos y arquitectura elegidos por la empresa, el resultado lo determina el modelo: responde la empresa.", "b": "El usuario interrumpe la cadena causal al pedir un estilo concreto, así que la responsabilidad recae únicamente en él.", "c": "Responden ambos por igual, porque el output surge de la combinación entre el pedido del usuario y el modelo entrenado.", "d": "La responsabilidad depende de que la empresa haya tenido intención de copiar; sin ese dolo, no hay infracción atribuible."}'::jsonb),
  ('etica-6-d', 6, 'd', '¿Qué medida de ingeniería reduce mejor el riesgo jurídico y ético?', '{"a": "Publicar un aviso de que las imágenes pueden parecerse a obras existentes y trasladar al usuario el chequeo de originalidad.", "b": "Registrar la procedencia de los datos respetando los opt-outs, testear memorization y filtrar outputs muy similares a obras existentes.", "c": "Trasladar el entrenamiento a una jurisdicción con excepciones de copyright más amplias y documentar esa decisión con cuidado.", "d": "Bajar la resolución de las imágenes generadas y agregar variaciones aleatorias para diferenciarlas de las portadas originales."}'::jsonb),
  ('etica-7-a', 7, 'a', '¿Por qué «no alcanzó el puntaje» no es una explicación suficiente?', '{"a": "Porque una explicación válida debe incluir el código fuente y los coeficientes exactos para poder reproducir el puntaje.", "b": "Porque la respuesta debía venir de la empresa proveedora, que es la única que conoce el funcionamiento interno del sistema.", "c": "Porque el municipio no le informó cuál fue el puntaje de corte ni la posición que ocupó Mariela en el ranking.", "d": "Porque no dice qué datos se usaron ni qué factores pesaron, qué habría cambiado el resultado, ni cómo se puede impugnar."}'::jsonb),
  ('etica-7-b', 7, 'b', 'Frente al secreto comercial invocado por la empresa, ¿qué criterio surge del material?', '{"a": "El secreto comercial prevalece sobre la explicación cuando el sistema lo compró un organismo público a un privado con contrato vigente.", "b": "El secreto cede en cuanto un ciudadano pide la explicación, ya que el interés del afectado desplaza al interés comercial.", "c": "El secreto comercial no extingue el derecho a la explicación: puede darse acceso reservado a un tribunal o auditor y ponderar.", "d": "El secreto sólo cede si la familia prueba antes que el sistema discriminó, y recién entonces se accede a su lógica."}'::jsonb),
  ('etica-7-c', 7, 'c', 'El argumento de que explicar permitiría «manipular» el sistema se parece a:', '{"a": "El argumento de Uber en Aslam: las familias, como los conductores, elegirían libremente cómo presentar sus datos al sistema.", "b": "La seguridad por oscuridad que el Supremo desarmó en BOSCO: un riesgo abstracto de vulneración no justifica la opacidad.", "c": "La defensa de los buscadores en Denegri: la información no debe alterarse porque afectaría la libertad de expresión de terceros.", "d": "La noción de drift: si las familias ajustan sus datos con el tiempo, el modelo pierde su relación con lo que predice."}'::jsonb),
  ('etica-7-d', 7, 'd', 'En el derecho argentino, ¿qué norma se activa más directamente si el rechazo es un acto administrativo basado sólo en el puntaje?', '{"a": "El art. 20 de la Ley 25.326: un acto que valora conductas no puede fundarse sólo en un perfil informatizado (nulidad insanable).", "b": "El art. 43 de la Constitución: el hábeas data permite a Mariela exigir que se publique la lógica de todos los algoritmos estatales.", "c": "El art. 17 del GDPR: Mariela puede pedir la supresión de sus datos del sistema, con lo que el rechazo pierde su fundamento.", "d": "El art. 4.7 de la Ley 25.326: los datos deben conservarse sólo por el tiempo necesario, por lo que el puntaje no puede usarse luego."}'::jsonb),
  ('etica-8-a', 8, 'a', '¿Qué dato muestra el problema de fairness con más precisión?', '{"a": "La accuracy global del 93 %, porque un valor tan alto indica que el modelo acierta con la misma calidad en todas las edades.", "b": "Que entre pacientes que sí desarrollaron sepsis, el sistema alerta al 90 % de los menores de 60 pero sólo al 64 % de los mayores de 75.", "c": "Que el modelo se entrenó con datos de un hospital de otro país y con población mayormente joven, distinta de la local.", "d": "Que los enfermeros descartan el 80 % de las alertas, lo que muestra que el modelo genera demasiadas falsas alarmas en mayores."}'::jsonb),
  ('etica-8-b', 8, 'b', 'En este sistema, ¿qué tipo de error tiene el costo más grave para el paciente?', '{"a": "Falso positivo: cada alerta innecesaria consume tiempo de enfermería y, acumuladas, desplazan la atención de los casos reales.", "b": "Ambos tienen un costo equivalente, porque un error en cualquier dirección obliga a repetir estudios y demora el diagnóstico.", "c": "Falso negativo: un paciente con sepsis que no recibe alerta puede quedar sin tratamiento a tiempo, con un daño difícil de revertir.", "d": "Ninguno resulta grave, porque cada alerta o su ausencia pasa por la revisión de enfermería antes de una decisión clínica."}'::jsonb),
  ('etica-8-c', 8, 'c', '¿Qué precedente apoya exigir validar el modelo en la población a la que se aplica?', '{"a": "State v. Loomis: el tribunal exigió validar cualquier algoritmo en cada población antes de usarlo en decisiones sobre personas.", "b": "GEMA c/ SUNO: el tribunal exigió validar los modelos con datos de la población local para evitar reproducir obras.", "c": "Costeja: el TJUE ordenó verificar que los datos usados por un servicio sigan siendo exactos y pertinentes para la población afectada.", "d": "Ewert v. Canada: instrumentos validados con una población se aplicaron a otra, y se cuestionó que aseguraran la exactitud debida."}'::jsonb),
  ('etica-8-d', 8, 'd', 'Sobre las alertas descartadas y la negativa a mover el threshold, ¿qué análisis es el más completo?', '{"a": "La supervisión se volvió formal por la fatiga de alertas, y el umbral es una decisión ética que requiere validarse por subgrupo.", "b": "Bajar el umbral para todos resuelve la brecha, porque en salud un falso negativo pesa más que cualquier costo operativo.", "c": "El umbral es una decisión técnica del proveedor, y al hospital le corresponde sólo capacitar a los enfermeros para revisar más alertas.", "d": "Los enfermeros son los responsables, porque descartan alertas sin revisarlas y así anulan la supervisión humana que el sistema prevé."}'::jsonb),
  ('etica-9-a', 9, 'a', '¿Qué concepto de la clase 5 describe lo que hace el algoritmo de RapiYa?', '{"a": "Automation: la plataforma sustituye tareas que antes hacían personas, y por eso los repartidores pierden su lugar de trabajo.", "b": "Augmentation: el algoritmo potencia la tarea del repartidor con mejores pedidos y rutas, y él conserva el control del trabajo.", "c": "Gestión algorítmica: el software asigna tareas, fija pagos, evalúa y sanciona, aunque el trabajador sigue haciendo el trabajo.", "d": "Exposure: las tareas de reparto son técnicamente automatizables, y el algoritmo es una etapa previa de esa sustitución."}'::jsonb),
  ('etica-9-b', 9, 'b', '¿Qué criterio usaron Uber v. Aslam y Glovo para calificar la relación?', '{"a": "Lo que firmaron las partes prevalece, salvo que el trabajador pruebe un vicio del consentimiento al aceptar la categoría.", "b": "La realidad del control y la dependencia prevalece sobre la etiqueta contractual que la empresa eligió para la relación.", "c": "La titularidad de las herramientas: quien usa su propio vehículo y su celular es autónomo, aunque la app organice su actividad.", "d": "La exclusividad: sólo es trabajador quien presta servicios a una única plataforma y no puede conectarse a otras."}'::jsonb),
  ('etica-9-c', 9, 'c', '«Los socios eligen cuándo conectarse.» ¿Cuál es la respuesta de la clase?', '{"a": "Es la paradoja de la flexibilidad: si rechazar baja el puntaje y el puntaje define pedidos y continuidad, la libertad es formal.", "b": "Es una prueba de autonomía real: quien decide cuándo conectarse no está subordinado, aunque el algoritmo lo evalúe.", "c": "Sólo sería relevante si RapiYa exigiera por contrato un mínimo de horas semanales, porque la subordinación requiere una obligación expresa.", "d": "Es irrelevante para el derecho laboral, porque las plataformas digitales intermedian entre partes y no emplean a nadie."}'::jsonb),
  ('etica-9-d', 9, 'd', 'Nicolás fue desconectado por calificaciones en días de lluvia y no puede reclamar. ¿Qué principio falla más directamente?', '{"a": "Sostenibilidad: las entregas bajo lluvia aumentan el gasto energético de la plataforma y agravan su huella ambiental.", "b": "Propiedad intelectual: el algoritmo de puntaje es un activo protegido y por eso Nicolás no puede acceder a su lógica.", "c": "Alfabetización en IA: Nicolás no comprende cómo se calculan los puntajes, por lo que no pudo prevenir su desconexión.", "d": "Contestabilidad y accountability: hay una sanción automática sin explicación ni instancia de revisión humana donde impugnarla."}'::jsonb),
  ('etica-10-a', 10, 'a', '¿Por qué «todos tienen acceso al tutor» no garantiza igualdad de oportunidades?', '{"a": "Porque el acceso formal sólo iguala oportunidades si cada estudiante dispone de la misma cantidad de horas de uso del tutor.", "b": "Porque los modelos generativos grandes rinden peor en el español regional que en inglés, lo que penaliza a las escuelas rurales.", "c": "Porque el acceso gratuito crea una dependencia del proveedor que luego encarece el servicio para las escuelas con menos recursos.", "d": "Porque la brecha ya no es binaria: velocidad, dispositivo, habilidades y conectividad determinan quién puede beneficiarse de la IA."}'::jsonb),
  ('etica-10-b', 10, 'b', 'Lo que advierten los docentes se describe mejor como:', '{"a": "Deskilling: al delegar sistemáticamente la tarea, los alumnos no desarrollan las capacidades para verificar lo que hace la IA.", "b": "Upskilling: los alumnos liberan tiempo de tareas rutinarias y pueden dedicarlo a aprender contenidos de mayor complejidad.", "c": "Augmentation: la IA amplía lo que el estudiante logra resolver, y él sigue siendo quien dirige y valida el resultado final.", "d": "Data drift: las respuestas del tutor se degradan con el tiempo y los alumnos no advierten que ya no son confiables."}'::jsonb),
  ('etica-10-c', 10, 'c', 'Sobre el data center en zona de sequías, ¿qué análisis corresponde?', '{"a": "Es aceptable si el modelo consume menos por consulta que los anteriores, porque la eficiencia compensa el impacto de la ubicación.", "b": "Es irrelevante porque la nube es inmaterial y el consumo de agua atribuible a la IA es marginal frente al de otras industrias.", "c": "La ubicación es una decisión con consecuencias ambientales y sociales: el agua y la matriz eléctrica de la zona importan.", "d": "Sólo importa el consumo del entrenamiento inicial, porque las consultas posteriores del tutor tienen un costo energético despreciable."}'::jsonb),
  ('etica-10-d', 10, 'd', '¿Qué respuesta refleja mejor el enfoque de la clase frente a la política provincial?', '{"a": "Postergar todo uso de IA educativa hasta que se cierre por completo la brecha de conectividad en las escuelas rurales.", "b": "Evitar el determinismo: conectividad y formación primero, modelo adecuado al problema, diseño que evite deskilling y medición de impacto.", "c": "Implementar el programa tal como está, porque el acceso masivo a la tecnología produce por sí mismo mejores resultados educativos.", "d": "Elegir el modelo más grande disponible para garantizar la misma calidad de respuesta a todas las escuelas de la provincia."}'::jsonb),
  ('etica-11-a', 11, 'a', '¿El historial de compras permite legítimamente inferir enfermedades para ajustar precios?', '{"a": "No: la inferencia sigue siendo dato personal y acá sensible (salud); que el dato de origen sea lícito no legitima cualquier uso.", "b": "Sí: el cliente entregó sus compras voluntariamente, y la inferencia es un resultado del modelo, no un dato que él declaró.", "c": "Sí, mientras la empresa no revele las inferencias a terceros ajenos al grupo, porque el riesgo surge sólo al compartirlas.", "d": "No, pero sólo porque las inferencias del modelo pueden resultar estadísticamente incorrectas y perjudicar a algunos clientes."}'::jsonb),
  ('etica-11-b', 11, 'b', 'La empresa dice que el cliente aceptó los términos. ¿Cuál es el análisis correcto?', '{"a": "Alcanza: aceptar los términos constituye consentimiento para los usos presentes y futuros que la empresa declare en ellos.", "b": "No hace falta consentimiento, porque la empresa tiene un interés legítimo en personalizar los precios y ofertas de sus clientes.", "c": "Sería inválido únicamente si el cliente fuera menor de edad o no tuviera capacidad para comprender los términos aceptados.", "d": "No alcanza: el consentimiento válido debe ser libre, específico, informado e inequívoco, y no cubre fines que no se informaron."}'::jsonb),
  ('etica-11-c', 11, 'c', 'Guardar todo sin plazo «por si sirve» y vender un índice de salud a una aseguradora vulnera sobre todo:', '{"a": "Exactitud: al guardar datos sin plazo se vuelven obsoletos, y venderlos así transmite a la aseguradora información desactualizada.", "b": "Limitación de conservación y de finalidad (y minimización): no guardar más de lo necesario ni reutilizar los datos para otro fin.", "c": "Portabilidad: al vender el índice a un tercero, el cliente pierde la posibilidad de llevarse sus datos a otra cadena.", "d": "Derecho al olvido: los datos quedan disponibles indefinidamente y el cliente debería poder pedir su desindexación."}'::jsonb),
  ('etica-11-d', 11, 'd', 'Dar menos descuentos a quienes el modelo infiere en dificultades económicas plantea además:', '{"a": "Un problema legal: al corregir la base jurídica del tratamiento, desaparece también el cuestionamiento ético del precio diferencial.", "b": "Un problema de transparencia: se corrige avisando que los precios son personalizados, porque así el cliente decide si acepta.", "c": "Un problema de fairness: aun con tratamiento lícito, el resultado perjudica de manera sistemática a quienes están en peor situación.", "d": "Un problema de drift: la situación económica inferida deja de ser válida cuando cambia la del cliente y el modelo no se actualiza."}'::jsonb),
  ('etica-12-a', 12, 'a', '¿Qué remedio piden, técnicamente, Ramiro y el exintendente?', '{"a": "Supresión de la fuente: que los diarios eliminen las notas originales de sus sitios, para que el contenido deje de existir.", "b": "Desindexación: que el buscador deje de vincular las notas con su nombre, aunque las publicaciones sigan disponibles en los diarios.", "c": "Rectificación: que se corrija la información publicada, porque en ambos casos las notas contienen datos inexactos o desactualizados.", "d": "Acceso: que el buscador les informe qué datos personales conserva sobre ellos y con qué criterio los ordena en sus resultados."}'::jsonb),
  ('etica-12-b', 12, 'b', '¿A qué precedente se parece más el pedido de Ramiro y qué resultado sugiere?', '{"a": "A Denegri: el paso del tiempo por sí solo lleva a la Corte a ordenar la desindexación de la información antigua.", "b": "A Loomis: como el buscador ordena resultados con un algoritmo opaco, debe desindexar sin realizar ponderación alguna.", "c": "A BOSCO: Ramiro puede exigir que se revele cómo se ordenan los resultados y desindexar si el criterio no es explicable.", "d": "A Costeja: un particular sin proyección pública, con deuda superada y relevancia perdida con el tiempo, inclina a desindexar."}'::jsonb),
  ('etica-12-c', 12, 'c', '¿Qué debería primar en el pedido del exintendente, siguiendo el razonamiento de la CSJN?', '{"a": "La privacidad, porque tras más de diez años toda noticia pierde relevancia y el titular recupera su derecho a no ser vinculado.", "b": "La privacidad, porque el candidato es una persona como cualquier otra y su condición política no modifica la ponderación.", "c": "La libertad de expresión e información: se trata de información veraz sobre una figura pública y un tema de interés público actual.", "d": "Un equilibrio parcial: desindexar la mitad de las notas, así ambos derechos quedan protegidos en la misma medida."}'::jsonb),
  ('etica-12-d', 12, 'd', 'Alguien dice: «Costeja y Denegri se contradicen, Europa olvida y Argentina recuerda». ¿Qué respondés?', '{"a": "Es incorrecto: ambos ponderan con el mismo método y llegan a resultados distintos porque las circunstancias son distintas.", "b": "Es correcto: el TJUE admite la desindexación y la CSJN la rechaza en cualquier circunstancia, por no reconocer el olvido.", "c": "Es correcto, y la diferencia se explica porque la ley argentina de datos personales es anterior al GDPR y no lo contempla.", "d": "Es incorrecto, porque en Denegri la Corte también ordenó desindexar los contenidos, igual que el TJUE en Costeja."}'::jsonb);
insert into preguntas_clave (pregunta_id, ok, explicacion, porque, desarrollo_modelo) values
  ('etica-1-a', 'b', 'Maximizar el total de sobrevivientes es el cálculo de utilidad neta típico del utilitarismo (Bentham, Mill): se ponderan consecuencias y se elige la alternativa con mayor saldo global.', '{"a": "Contractualismo pide reglas justificables ante todos, incluido el peor ubicado; acá excluye sistemáticamente a los crónicos y nadie la acordó.", "c": "Aplicar una regla uniforme no es deontología: ésta mira deberes y dignidad con independencia del resultado, y acá el criterio es justamente el resultado.", "d": "La prudencia implica auditar el modelo; delegar sin revisar se parece más al vicio por exceso (credulidad ciega)."}'::jsonb, 'El problema es una asignación de recursos escasos basada en un score que concentra el perjuicio en pacientes crónicos. Chocan la eficiencia (salvar más vidas) y la igual consideración de cada paciente. El criterio de la dirección es utilitarista y cae en su crítica central: justificar un daño sistemático a una minoría. Desde el contractualismo, nadie aceptaría bajo el velo de ignorancia una regla que lo excluya por ser crónico sin revisión. Recomiendo usar el score sólo como insumo: validación por subgrupos (el modelo puede estar peor calibrado para crónicos, como en Ewert), criterios de asignación públicos y discutidos con afectados, revisión clínica obligatoria con autoridad para apartarse (supervisión material) y registro de cada decisión. Responde la dirección del hospital como deployer, no el sistema.'),
  ('etica-1-b', 'd', 'La crítica central al utilitarismo en la clase 1 es el riesgo de justificar injusticias: si perjudicar a una minoría beneficia mucho a la mayoría, el cálculo lo avala.', '{"a": "Eso describe una caricatura de la deontología; el utilitarismo, al revés, razona sólo con consecuencias.", "b": "El utilitarismo trabaja con expectativas y probabilidades; no requiere certeza, así que no es la objeción central.", "c": "La supervisión humana no es una preferencia personal; la objeción de fondo que marca la clase es distributiva, no la autonomía de la médica."}'::jsonb, null),
  ('etica-1-c', 'a', 'Rawls y el velo de ignorancia: una regla es legítima si la aceptaríamos sin saber si seremos el paciente crónico. Es la misma lectura que la cátedra hace del caso Bakalar y del repaso (caso 3).', '{"b": "Podría mencionarse como efecto, pero el fundamento del pedido es la legitimidad de la regla, no su utilidad.", "c": "La deontología pide no tratar a nadie sólo como medio, pero no prescribe un procedimiento de consulta; lo que fundamenta el pedido es la justificabilidad de la regla.", "d": "La virtud mira el carácter del agente que decide, no la validación de las reglas ante los afectados."}'::jsonb, null),
  ('etica-1-d', 'c', 'La clase 1 plantea la virtud en ciencia de datos: defecto = rechazar todo modelo, exceso = aceptar ciegamente, virtud = usarlo auditando críticamente. Además, es supervisión humana material.', '{"a": "El automation bias es sobreconfianza en la máquina; ella hace lo contrario: revisa lo que el sistema propone.", "b": "No rechaza el sistema ni ignora las consecuencias: exige revisarlo antes de aplicarlo.", "d": "Rechazar todo modelo sería el defecto; ella no lo descarta, lo somete a revisión caso por caso."}'::jsonb, null),
  ('etica-2-a', 'c', 'La clase 1 define el sesgo de autoridad tecnológica: asumir que lo que sale de un sistema automatizado debe ser correcto; el algoritmo no duda y encubre errores.', '{"a": "Nada indica que el contador tuviera una creencia previa; el problema es la confianza en la herramienta.", "b": "La omisión sería no responder; el sistema respondió e inventó un dato.", "d": "El drift es un deterioro predictivo por cambios en los datos; acá hay una alucinación, un dato inventado."}'::jsonb, 'Hay dos problemas. Primero, una alucinación que el contador trasladó por sesgo de autoridad tecnológica: el texto fluido parecía verdadero. En Walters el proveedor quedó protegido por advertencias, sin difusión y sin dolo, pero la cátedra critica esos argumentos: los disclaimers no bastan y puede haber responsabilidad por omitir controles. Aun así, el primer responsable frente al cliente es el estudio, que tiene un deber profesional de verificar antes de enviar. Segundo, privacidad: se cargaron datos de terceros, un dato sensible de salud e información bajo secreto profesional; el consentimiento del estudio no sustituye la base jurídica de los titulares. Propongo: verificación obligatoria de todo output con consecuencias, prompts desidentificados (categorías y roles, reinserción local), herramientas autorizadas con configuración de no entrenamiento y retención mínima, y registro de qué se usó en cada informe para poder reconstruir y responder.'),
  ('etica-2-b', 'a', 'Las críticas al fallo Walters: los disclaimers no alcanzan porque el lenguaje induce confianza indebida, y puede haber responsabilidad por diseño o negligencia aun sin intención.', '{"b": "La clase también marca el deber del usuario profesional de verificar; no hay un único responsable.", "c": "La crítica apunta justamente a que ese consentimiento es irreal: nadie lee ni pondera esas advertencias.", "d": "Puede haber responsabilidad por diseño o por negligencia aun sin intención; es la crítica central al fallo."}'::jsonb, null),
  ('etica-2-c', 'd', 'Clase 1: un prompt puede contener datos personales, sensibles y confidenciales de varios titulares; el consentimiento del usuario no reemplaza la base para terceros. In re OpenAI muestra que «borrar» tiene capas.', '{"a": "Es lo que la clase niega: aceptar términos no legitima el tratamiento de datos de terceros.", "b": "Resumir implica recoger, consultar y combinar datos: es tratamiento.", "c": "In re OpenAI: ocultar de la cuenta no es eliminar ni destruir; puede haber órdenes de conservación."}'::jsonb, null),
  ('etica-2-d', 'b', 'Privacidad desde el diseño del prompting: plantillas con categorías, ejemplos ficticios, roles en lugar de nombres, análisis local reinsertando identidades después.', '{"a": "Las iniciales y el CUIT siguen identificando a las personas; no hay minimización de lo expuesto.", "c": "Cifrar el canal no reduce lo que se expone al proveedor; la necesidad contextual pide enviar sólo lo necesario.", "d": "Es la lógica de maximización que choca con la minimización, y no elimina las alucinaciones."}'::jsonb, null),
  ('etica-3-a', 'd', 'Clases 2 y 4: eliminar el atributo protegido no elimina el sesgo si otras variables lo codifican indirectamente. El algoritmo puede discriminar sin conocer la característica.', '{"a": "Al quitarlos, la columna desaparece; el problema son las otras variables que correlacionan con esas características.", "b": "Se puede medir por grupo con datos desagregados (lo hizo la ONG); el problema es que otras variables codifican el atributo.", "c": "No es un problema de accuracy ni de sobreajuste, sino de variables que funcionan como proxies."}'::jsonb, 'El modelo no es ciego: código postal, recargas en efectivo y tipo de celular son proxies de nivel socioeconómico, y el dataset histórico arrastra sesgo sistémico. La accuracy global del 90 % oculta la distribución de errores: entre buenos pagadores, se aprueba al 88 % en barrios céntricos y sólo al 61 % en populares. Eso viola equal opportunity y, por lo tanto, también equalized odds. «Refleja el comportamiento histórico» no es defensa: reproducir desigualdad con precisión es perpetuarla. Recomiendo adoptar equal opportunity como métrica principal, porque el objetivo del producto es prestar a quien puede pagar y lo injustificable es que un buen pagador tenga menos chance por su barrio; aceptar que esa elección es normativa (no se pueden cumplir todas las métricas) y documentarla. Medidas: revisar y justificar cada variable, test por subgrupo antes de cada versión, explicación contrafactual al rechazado, revisión humana ante rechazos y responsables asignados. En el AI Act, el scoring crediticio es alto riesgo.'),
  ('etica-3-b', 'b', 'Equal opportunity iguala la tasa de verdaderos positivos entre quienes merecían el positivo. 88 vs 61 es una violación clara. Equalized odds también falla porque exige TPR y FPR iguales.', '{"a": "Los porcentajes de la ONG están condicionados a quienes pagaron o no, no a quienes fueron aprobados; no permiten calcular predictive parity.", "c": "Las cifras no son tasas totales de aprobación: están condicionadas al comportamiento real de pago.", "d": "Un FPR parecido no alcanza; la diferencia en la tasa de verdaderos positivos (88 vs 61) ya es una violación."}'::jsonb, null),
  ('etica-3-c', 'c', 'Clase 4 (NIST): el sesgo sistémico viene de estructuras previas. Clase 2: reproducir patrones históricos no es neutralidad, es perpetuación. Es la misma frase de NEXUS en IMPULSO.', '{"a": "Datos verdaderos pueden codificar desigualdad; un sistema técnicamente impecable puede ser éticamente problemático.", "b": "Publicar el código no corrige el sesgo ni equivale a explicarlo.", "d": "La cátedra no admite esa división: quien despliega el sistema responde por sus efectos, incluido el sesgo sistémico."}'::jsonb, null),
  ('etica-3-d', 'a', 'Pasos de cierre de la clase 2: identificar datos adecuados, evaluar fairness desagregada y asumir que elegir la métrica es una decisión normativa, no sólo técnica.', '{"b": "Mejorar accuracy con categorías protegidas es exactamente el dilema de Loomis, no una solución.", "c": "Cambia la distribución de errores sin mirar a los grupos; puede empeorar la brecha.", "d": "Más complejidad suele restar explicabilidad y no ataca el sesgo que traen los datos."}'::jsonb, null),
  ('etica-4-a', 'a', 'Concept drift es el cambio en la relación variable → objetivo (como «operar a las 3 AM» y fraude). La caída 88 → 71 es la evidencia de model drift, que ocurre aunque nadie toque el código.', '{"b": "Ese sería un cambio de distribución; acá el punto central es que la variable perdió significado, no que salga de rango.", "c": "El model drift no requiere cambios de código; nada indica que el proveedor modificara el sistema.", "d": "Predijo bien (88 %) hasta que cambió el contexto; no siempre fue mala, dejó de serlo."}'::jsonb, 'Fallaron tres cosas. Técnica: con la cursada híbrida, la asistencia presencial perdió relación con el compromiso (concept drift) y la precisión cayó de 88 a 71 % (model drift) sin que nadie lo detectara, porque no había monitoreo. Ética: el semáforo se usó para dar menos apoyo a los rojos, lo que puede producir el abandono que predice; ALTAI pedía preguntar si la clasificación ayuda o estigmatiza. Institucional: responsabilidad diluida entre área académica, proveedor y tutores. Responde la universidad como deployer frente al estudiante, y el proveedor por la falta de validación. Recomiendo suspender las consecuencias automáticas del color, invertir el uso (rojo = más apoyo, nunca menos), revalidar con variables actuales y datos por subgrupo, monitoreo con alertas de desempeño, informar a los estudiantes que son clasificados con posibilidad de cuestionar, y un responsable nombrado que apruebe cada versión.'),
  ('etica-4-b', 'c', 'Clase 2 (ALTAI, riesgo de abandono): si la clasificación reduce recursos y expectativas, el algoritmo no es un espejo neutral, contribuye a producir el resultado.', '{"a": "No hay una categoría protegida escrita en la regla del sistema.", "b": "Describe un vicio cognitivo de los tutores; el riesgo para los rojos es que la clasificación contribuye a producir el resultado.", "d": "Reentrenar no corrige que la clasificación se use para dar menos apoyo a quien más lo necesita."}'::jsonb, null),
  ('etica-4-c', 'b', 'Es la pregunta de bienestar que la clase asocia a ALTAI en el ejemplo del riesgo de abandono: la intención no basta, el diseño del uso importa.', '{"a": "La documentación técnica y la precisión no dicen nada sobre el efecto de la clasificación en el alumno.", "c": "Es una pregunta de seguridad de datos, válida pero distinta: no evita el efecto del uso de la clasificación.", "d": "Mide desempeño técnico, no el impacto sobre el bienestar y las oportunidades de cada estudiante."}'::jsonb, null),
  ('etica-4-d', 'd', 'Caso Bakalar (clase 2): compartida ≠ diluida. La salida es reglas previas, trazabilidad, afectados que puedan cuestionar y alguien que siempre responda.', '{"a": "Cuando cada uno dice «sólo hice mi parte» y nadie responde, es responsabilidad diluida, no compartida.", "b": "Las decisiones de uso y de contrato son de la universidad; culpar a un solo eslabón no resuelve el problema.", "c": "Culpar sólo al eslabón final repite el patrón del caso Uber; el diseño y el contrato dependen de otros."}'::jsonb, null),
  ('etica-5-a', 'b', 'Claves de la actividad UE: el reconocimiento de emociones en lugares de trabajo y establecimientos educativos es práctica prohibida salvo excepciones. Principios: dignidad, privacidad, autonomía.', '{"a": "El empleo es un área de alto riesgo, pero esta práctica específica sube un escalón: es prohibida.", "c": "Informar no alcanza cuando la práctica está prohibida.", "d": "Inferir emociones de empleados no es riesgo mínimo; está en la lista de prohibiciones."}'::jsonb, 'Producto 1: inferir emociones de trabajadores es práctica prohibida como regla; protege dignidad, privacidad y autonomía. Recomendación: retirarlo del mercado europeo (multas de hasta €35 M o 7 %). Producto 2: riesgo de transparencia; basta con informar claramente que es IA, porque el problema ético es el engaño, no el chatbot. Producto 3: alto riesgo (empleo). La empresa, como provider, debe tener gestión de riesgos, datos de entrenamiento representativos y evaluados por sesgo, documentación técnica previa, logs automáticos y robustez; el banco, como deployer, debe usarlo conforme y garantizar supervisión humana efectiva. Hoy la supervisión es formal: RR.HH. sólo ve finalistas. Propongo muestrear descartes con revisión humana, métricas de fairness por grupo, explicación a candidatos descartados y registro de cada decisión. Y revisar periódicamente el calendario del AI Act, que cambió con el AI Omnibus.'),
  ('etica-5-b', 'a', 'Clave B de la actividad: transparencia. Medida: informar claramente que es un sistema de IA (salvo que sea obvio por el contexto).', '{"b": "Un nombre humano no es por sí una técnica subliminal perjudicial; el encuadre de la cátedra es transparencia.", "c": "La atención comercial básica no está entre las áreas de alto riesgo mencionadas.", "d": "Los chatbots sí tienen obligación de transparencia, traten o no datos sensibles."}'::jsonb, null),
  ('etica-5-c', 'd', 'Clase 3: provider desarrolla y pone en el mercado bajo su nombre; deployer lo usa bajo su autoridad. Es el mismo ejemplo de la clase (empresa de selección + banco).', '{"a": "Provider es quien desarrolla y pone en el mercado; el banco lo usa bajo su autoridad, que es el rol de deployer.", "b": "Invierte los roles.", "c": "El deployer también tiene obligaciones (por ejemplo, supervisión humana y uso conforme)."}'::jsonb, null),
  ('etica-5-d', 'c', 'Ejemplo del reclutamiento en la clase 3: si el algoritmo eliminó a miles antes, el humano al final no revierte que la decisión material ya se tomó. El alto riesgo exige supervisión efectiva, no formal.', '{"a": "El AI Act exige medidas efectivas, no meramente formales.", "b": "Ver el score de los finalistas no controla los descartes previos.", "d": "Una auditoría anual espaciada no es supervisión efectiva de decisiones que se toman de forma continua."}'::jsonb, null),
  ('etica-6-a', 'c', 'En Múnich, la memorization suficientemente reproducible fue reproducción en sentido jurídico. El grado de memorization no es sólo técnico: es determinante.', '{"a": "El volumen no define la infracción; lo decisivo es si las obras reaparecen.", "b": "Es la defensa de «aprende patrones»; el tribunal la descartó cuando las obras eran reproducibles.", "d": "El tribunal no se apoyó en el lugar del servidor; miró si los outputs reproducían las obras."}'::jsonb, 'Hay que separar tres momentos. En el entrenamiento se usaron obras con reserva de derechos legible por máquina, por lo que la excepción de TDM no las cubre. En el modelo hay memorization: portadas conocidas son reproducibles con prompts simples, lo que siguiendo GEMA c/ SUNO configura reproducción. En el output, la responsabilidad es de PincelAI: el usuario no describe composición ni detalles, mientras la empresa eligió datos y arquitectura. El argumento de los servidores en EE.UU. no alcanza porque las obras reaparecen sustancialmente. Detrás hay una pregunta ética: los ilustradores son el insumo esencial y no participan del valor que genera el modelo. Resolvería a favor de los autores (cese, información sobre uso y daños) y exigiría: procedencia de datos con respeto de opt-outs, tests de memorization antes de cada versión, filtros de similitud en outputs, resumen público del dataset (art. 53 AI Act para GPAI) y un canal de reclamo para titulares.'),
  ('etica-6-b', 'd', '§ 44b UrhG: para obras online la reserva debe ser machine-readable; si existe, el TDM no aplica. El AI Act (art. 53) exige a GPAI respetar esas reservas.', '{"a": "La excepción tiene condiciones; el opt-out del titular la excluye.", "b": "El material no condiciona la excepción a la gratuidad: lo que la excluye es la reserva del titular.", "c": "Se discutió justamente con música en GEMA c/ SUNO; el criterio no es el tipo de obra."}'::jsonb, null),
  ('etica-6-c', 'a', 'El tribunal atribuyó los outputs a SUNO: prompts sin melodía ni arreglo, SUNO elegía datos y arquitectura, y la decisión material sobre el output era del sistema.', '{"b": "Es la defensa de SUNO que el tribunal rechazó.", "c": "El fallo no repartió en partes iguales; atribuyó los outputs a SUNO.", "d": "Los outputs que reproducen obras generan responsabilidad sin necesidad de probar intención."}'::jsonb, null),
  ('etica-6-d', 'b', 'Medidas del grupo de ingeniería/compliance: data provenance + opt-out, filtros y tests de memorization, detección de similitud en outputs + logging, resumen público del dataset y notice & takedown.', '{"a": "Un disclaimer no elimina la reproducción ni la responsabilidad.", "c": "Es arbitraje regulatorio; no corrige que los outputs reproduzcan obras.", "d": "Esconde el síntoma sin resolver la memorization."}'::jsonb, null),
  ('etica-7-a', 'd', 'Clase 4: una buena explicación contesta qué datos, qué factores, qué lo habría cambiado (contrafactual) y cómo cuestionarlo. Dun & Bradstreet: debe permitir comprender y cuestionar.', '{"a": "Transparencia no es publicar todo: la persona necesita una explicación comprensible, no miles de líneas.", "b": "Quien decide sobre la persona es quien debe responder; no puede delegar la explicación.", "c": "Saber el puntaje o la posición es información, no explicación: no dice qué factores pesaron ni cómo cuestionar."}'::jsonb, 'Fallaron la explicabilidad (sólo se informó el resultado), la contestabilidad (no hay revisión) y la transparencia institucional (no se sabe qué criterios usa el municipio). Chocan el secreto comercial y la «seguridad» de la empresa con el derecho de Mariela a comprender y cuestionar una decisión sobre un derecho social. Siguiendo Dun & Bradstreet, el secreto no extingue la explicación y puede darse acceso reservado; siguiendo BOSCO, cuando un software ejerce potestades públicas su lógica integra la motivación del acto y el riesgo de manipulación debe probarse en concreto. Como es un acto administrativo basado únicamente en un puntaje, el art. 20 de la Ley 25.326 permite plantear su nulidad; además puede ejercer hábeas data para conocer sus datos. Rediseño: criterios públicos, explicación contrafactual («con cobertura de horario nocturno hubiera entrado»), revisión humana con autoridad antes de cada rechazo, logs con versión y puntaje, y evaluación de que variables como horario laboral no penalicen a familias más vulnerables.'),
  ('etica-7-b', 'c', 'Dun & Bradstreet: el secreto comercial no extingue el derecho; la información protegida puede ir a una autoridad en procedimiento reservado. En BOSCO, además, pesa el uso público del software.', '{"a": "El uso público del software refuerza el deber de explicar (BOSCO); no lo anula.", "b": "Tampoco desaparece de forma automática: se pondera caso por caso.", "d": "Exigir prueba previa sin acceso a la lógica deja al afectado indefenso; es el problema que BOSCO resuelve."}'::jsonb, null),
  ('etica-7-c', 'b', 'En BOSCO se alegó que revelar el código generaba vulnerabilidades. El Supremo exigió un riesgo concreto y habló de seguridad por escrutinio; lo mismo aparece en IMPULSO («engañar al algoritmo»).', '{"a": "Aslam trata sobre subordinación laboral, no sobre opacidad.", "c": "Denegri pondera privacidad y libertad de expresión, no el secreto de un algoritmo.", "d": "El drift es un cambio en los datos del mundo, no una estrategia para sostener la opacidad."}'::jsonb, null),
  ('etica-7-d', 'a', 'Clase 6: art. 20 Ley 25.326, idea clave 3. Un acto administrativo con único fundamento en un tratamiento informatizado que defina el perfil es nulo.', '{"b": "El art. 43 consagra el hábeas data (acceso a los datos propios), no la publicación de todos los algoritmos.", "c": "El GDPR no rige directamente acá, y la supresión no resuelve la falta de fundamento del acto.", "d": "Regula el plazo de conservación, no que el acto administrativo se apoye únicamente en un perfil automatizado."}'::jsonb, null),
  ('etica-8-a', 'b', 'Es una diferencia de verdaderos positivos entre grupos (equal opportunity). La accuracy global la ocultaba: accuracy ≠ fairness.', '{"a": "Es precisamente el promedio que oculta el problema: accuracy no es fairness.", "c": "Es la causa probable (representación), no la medida que muestra la disparidad.", "d": "Muestra un problema de uso humano (fatiga) y no mide por sí mismo la disparidad entre grupos."}'::jsonb, 'El 93 % global oculta una violación de equal opportunity: entre quienes tuvieron sepsis, el sistema alerta al 90 % de los menores de 60 y sólo al 64 % de los mayores de 75. Probablemente por sesgo de representación: se entrenó con población joven de otro país y nunca se validó localmente (Ewert). En este dominio el falso negativo es el error crítico, porque su costo es irreversible y recae sobre los más vulnerables. Al mismo tiempo, 40 alertas por turno producen fatiga y automation bias al revés: se descarta sin revisar, y la supervisión es formal. Chocan eficiencia operativa y derecho a la salud en igualdad. Recomiendo: revalidar con datos locales desagregados por edad, recalibrar o fijar umbrales con evaluación de impacto por grupo (decisión clínica y ética, documentada), reducir alertas de baja calidad, protocolo que obligue a registrar por qué se descarta una alerta y monitoreo de drift. Responde el hospital como deployer; el proveedor por no advertir los límites de validación.'),
  ('etica-8-b', 'c', 'Clase 4: en sistemas médicos el falso negativo puede ser irreversible. Elegir threshold es elegir qué error tolerar y sobre quién recae.', '{"a": "Tiene costos (y la fatiga importa), pero recaen más sobre el sistema y no se comparan con una sepsis no tratada.", "b": "Los costos son asimétricos; por eso la accuracy global no alcanza para evaluar el sistema.", "d": "Si descartan el 80 % sin revisar, la supervisión humana no protege al paciente."}'::jsonb, null),
  ('etica-8-c', 'd', 'Ewert: instrumentos validados sobre población no indígena aplicados a indígenas. Lección: un modelo validado en una población no está validado en todas; puede ser obligación legal.', '{"a": "Loomis no impuso esa exigencia; admitió el uso del algoritmo con límites y advertencias.", "b": "GEMA trata de copyright y memorization, no de validación poblacional.", "c": "Costeja trata de desindexación en buscadores, no de validar modelos."}'::jsonb, null),
  ('etica-8-d', 'a', 'Combina tres ideas: supervisión formal vs material (descartes sin revisar), threshold como decisión ética sobre qué error tolerar, y evaluación por subgrupo antes de decidir.', '{"b": "Ignora el costo de la fatiga, que ya vacía la supervisión, y no valida el efecto por grupo.", "c": "La cátedra insiste en que el umbral no es sólo técnico: implica elegir qué error tolerar y sobre quién recae.", "d": "Culpa al eslabón final sin mirar el diseño que genera 40 alertas por turno."}'::jsonb, null),
  ('etica-9-a', 'c', 'Algorithmic management: el trabajador sigue existiendo pero el software decide qué tarea recibe, cuánto cobra, cómo es evaluado y cuándo es sancionado.', '{"a": "Nicolás sigue haciendo el trabajo; no hay sustitución.", "b": "No se trata de ayudar a la tarea sino de dirigir y sancionar al trabajador.", "d": "La exposición a la automatización no es lo que describe el caso: hoy el algoritmo dirige, no reemplaza."}'::jsonb, 'El algoritmo de RapiYa ejerce poder de dirección: fija tarifas, asigna pedidos y franjas según puntaje, penaliza rechazos y sanciona con desconexión automática. Como en Uber v. Aslam y Glovo, la realidad del control prevalece sobre la etiqueta de «socio independiente»: hay ajenidad (la plataforma es el activo esencial y controla clientes y precios) y dependencia (el puntaje condiciona el acceso al trabajo). La libertad de conectarse es formal: rechazar tiene costos que la vacían. Además, la sanción se basó en calificaciones influidas por la lluvia, un factor ajeno al desempeño (sesgo de medición), sin explicación ni revisión: fallan contestabilidad y accountability. Calificaría la relación como laboral y exigiría informar los criterios del puntaje, explicar cada sanción, revisión humana antes de desconectar y corregir el rating por factores externos. La automatización no elimina al empleador: cambia su forma.'),
  ('etica-9-b', 'b', 'Uber v. Aslam privilegió la realidad de la relación sobre la denominación; Glovo verificó ajenidad y dependencia en la organización algorítmica del trabajo.', '{"a": "Los tribunales justamente penetraron la forma contractual para mirar la realidad.", "c": "No es el criterio del material: pesó la organización algorítmica del trabajo, no de quién eran las herramientas.", "d": "No es el criterio del material; lo que contó fue el control y la dependencia."}'::jsonb, null),
  ('etica-9-c', 'a', 'La paradoja de la flexibilidad: ¿cuánta libertad real hay cuando las consecuencias de no aceptar son suficientemente negativas? En Glovo, rechazar deterioraba la valoración y el acceso a horarios.', '{"b": "Los tribunales vieron que la autonomía era muy limitada pese a la libertad horaria.", "c": "No hace falta una obligación expresa: el control opera a través del puntaje.", "d": "Uber y Glovo muestran lo contrario: se verificó dependencia."}'::jsonb, null),
  ('etica-9-d', 'd', 'Sanción automática sin revisión: falla la contestabilidad (no puede impugnar) y la accountability (nadie responde). Además, el rating incorpora factores ajenos al trabajador (bias de medición).', '{"a": "No es el problema central del caso.", "b": "La PI puede invocarse contra la transparencia, pero no es el principio que el caso vulnera.", "c": "Aun entendiendo el modelo, seguiría sin poder impugnar la sanción."}'::jsonb, null),
  ('etica-10-a', 'd', 'Clase 5: la digital divide pasó a preguntar con qué velocidad, dispositivo y habilidades; la AI divide es la desigualdad en la capacidad efectiva de beneficiarse. Formalmente todos tienen acceso; no la misma oportunidad.', '{"a": "Igualdad formal no es equidad: las mismas horas con peores condiciones no iguala.", "b": "Es un factor posible, pero no es lo que plantea el caso.", "c": "El costo futuro no es lo que plantea el caso; la brecha es la desigualdad en la capacidad efectiva de beneficiarse."}'::jsonb, 'El programa parte de un supuesto determinista: dar acceso a la IA mejora la educación. Pero con 40 % de escuelas rurales mal conectadas y celulares compartidos, la AI divide hace que los que ya están mejor aprovechen más: todos tienen acceso formal, no la misma oportunidad. Además, un tutor que resuelve tareas produce deskilling: los alumnos entregan sin entender y pierden la capacidad de verificar al sistema. Ambientalmente, un modelo grande usado masivamente concentra el costo en la inferencia y el data center en zona de sequía traslada la huella hídrica a una comunidad que no decidió. Recomiendo aprobarlo con condiciones: conectividad y dispositivos primero en las escuelas rurales, formación docente y de alumnos (AI literacy), un tutor que guíe sin dar respuestas finales, un modelo del tamaño adecuado, ubicación del cómputo con agua disponible y matriz limpia, y medición pública de resultados educativos y consumo.'),
  ('etica-10-b', 'a', 'Deskilling: pérdida de capacidades por delegar permanentemente; la pregunta de la clase es quién detectará el error de la IA.', '{"b": "El upskilling requiere formación y diseño; acá el tutor reemplaza el aprendizaje.", "c": "La augmentation supone que la persona sigue siendo central; acá entregan sin entender.", "d": "No hay un modelo predictivo que se deteriore: lo que se pierde son capacidades de los alumnos."}'::jsonb, null),
  ('etica-10-c', 'c', 'UNEP: el impacto hídrico varía por diseño, refrigeración y ubicación, especialmente con estrés hídrico. La nube es infraestructura física.', '{"a": "Efecto rebote: más eficiencia por tarea puede aumentar el consumo total cuando el uso es masivo.", "b": "La clase dice lo contrario: la nube es infraestructura física y el estrés hídrico importa (UNEP).", "d": "A gran escala, la inferencia acumulada puede superar al entrenamiento."}'::jsonb, null),
  ('etica-10-d', 'b', 'Evitar el determinismo tecnológico (PNUD): el resultado depende de decisiones. IA inclusiva exige conectividad y AI literacy; Green AI pide modelo adecuado, ubicación y medición.', '{"a": "Es la parálisis del vicio por defecto; la clase no propone prohibir.", "c": "Es determinismo tecnológico, justo lo que la clase pide evitar.", "d": "Green AI: no se trata de usar siempre el modelo más grande sino uno adecuado al problema."}'::jsonb, null),
  ('etica-11-a', 'a', 'Clase 6 (parte II): una inferencia no deja de ser dato personal porque nadie la escribió. Clase 1: Meta c/ Bundeskartellamt, compras ordinarias pueden permitir inferir salud. La salud es dato especialmente protegido.', '{"b": "Es el razonamiento que la clase rechaza expresamente.", "c": "El problema existe aunque no se comparta: el tratamiento mismo carece de base y de finalidad legítima.", "d": "Aun siendo correctas, el uso sería ilegítimo."}'::jsonb, 'La cadena trata datos inferidos de salud y situación económica a partir de compras: son datos personales aunque el cliente nunca los haya declarado, y los de salud son sensibles (art. 9 GDPR; Ley 25.326). El consentimiento obtenido con 40 páginas «para beneficios» no es específico ni informado respecto de inferencias clínicas, precios diferenciados o venta a aseguradoras. Se vulneran limitación de finalidad (de fidelización a scoring de salud para terceros), minimización (inferir más de lo necesario para dar puntos) y conservación (guardar sin plazo; art. 4.7 Ley 25.326). Por ofrecer bienes a personas en la UE, el GDPR puede alcanzar la tienda online. Además, aun con base jurídica, dar menos descuentos a quienes infiere en dificultades es injusto: lícito no es equitativo. Medidas: cesar las inferencias sensibles y la venta del índice, DPIA previa a todo profiling, configuración protectora por defecto, plazos de conservación, consentimiento granular y separado, y evaluación de impacto distributivo de los precios personalizados.'),
  ('etica-11-b', 'd', 'Idea clave 1 (clase 6): el consentimiento no es la única base, pero cuando se usa debe ser libre, específico, informado e inequívoco. 40 páginas para «beneficios» no informan inferencias de salud ni venta a aseguradoras.', '{"a": "La cátedra pregunta justamente si páginas de términos generales son consentimiento informado.", "b": "El interés legítimo debe ponderarse con los derechos del titular; no habilita tratar datos de salud para cobrar más.", "c": "El vicio está en la falta de especificidad e información, no sólo en la capacidad del cliente."}'::jsonb, null),
  ('etica-11-c', 'b', 'Principios del art. 5 GDPR (y art. 4.7 Ley 25.326): no conservar más de lo necesario; no usar para un fin distinto e incompatible; recolectar sólo lo necesario.', '{"a": "No es el problema principal descrito: el caso trata de cuánto se guarda y para qué se usa.", "c": "La portabilidad es un derecho del titular, no el principio vulnerado por la conservación y la venta.", "d": "No hay buscador ni desindexación en juego."}'::jsonb, null),
  ('etica-11-d', 'c', 'Clase 6 (parte II): protección de datos y fairness son dimensiones distintas; un dataset legal puede dar un resultado discriminatorio. Y en ética, cargar el costo sobre quien menos puede es la pregunta distributiva.', '{"a": "Legal no es lo mismo que ético: cumplir con datos no garantiza equidad.", "b": "Avisar no corrige el perjuicio distributivo.", "d": "El drift no es el núcleo; el problema existe desde el diseño."}'::jsonb, null),
  ('etica-12-a', 'b', 'Idea clave 2: eliminar la fuente, desindexar, rectificar y bloquear son remedios distintos. Piden al buscador desvincular resultados, como en Costeja.', '{"a": "Se dirigen al buscador y no piden borrar las notas originales.", "c": "Las notas no son falsas: la veracidad no está discutida.", "d": "No piden conocer sus datos; piden que ciertos resultados no aparezcan."}'::jsonb, 'Ambos piden desindexación, no borrar las notas. El buscador trata datos y es responsable (Costeja), y su ranking define visibilidad, por eso debe ponderar con las mismas preguntas: ¿es verdadera?, ¿sigue siendo actual?, ¿tiene proyección pública?, ¿hay interés público?, ¿qué antigüedad y qué daño hoy? Ramiro: particular, información veraz pero de un concurso cerrado y pagado hace más de diez años, sin interés público actual y con daño concreto en su trabajo. Como en Costeja, la vinculación permanente con su nombre ya no está justificada: desindexo, y los diarios conservan las notas. Exintendente: figura pública que busca un cargo, información veraz sobre su gestión y aún relevante para el debate electoral. Como en Denegri, prevalece la libertad de información: rechazo, salvo que acreditara contenido ilícito o una vinculación claramente lesiva. No hay contradicción: el método es el mismo y las circunstancias inclinan la balanza en sentidos opuestos.'),
  ('etica-12-b', 'd', 'Costeja: información verdadera y lícita, pero la vinculación permanente con el nombre dejó de estar justificada (inadecuada, no pertinente, excesiva por el tiempo).', '{"a": "Denegri rechazó la desindexación; y la mera antigüedad no alcanza.", "b": "Loomis no trata el derecho al olvido.", "c": "BOSCO trata del acceso al código de la Administración, no de buscadores privados."}'::jsonb, null),
  ('etica-12-c', 'c', 'Denegri: información veraz sobre una figura pública y un hecho de interés público exige protección intensa de la libertad de expresión; desindexar también restringe.', '{"a": "Denegri: lo antiguo no es automáticamente irrelevante.", "b": "La proyección pública es justamente un factor central de la ponderación.", "d": "No es un criterio del material; la ponderación no es aritmética."}'::jsonb, null),
  ('etica-12-d', 'a', 'Idea clave 4: no son sentencias contradictorias. Particular + deuda superada vs figura pública + interés público. La CSJN dejó abierta la tutela excepcional.', '{"b": "La CSJN dejó abierta la tutela excepcional ante contenido ilícito, daño concreto y vinculación lesiva.", "c": "La diferencia no se explica por la antigüedad de la ley sino por las circunstancias de cada caso.", "d": "En Denegri la CSJN revocó la desindexación."}'::jsonb, null);
